import{_ as o,o as n,c as s,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"2019-03-19:: Crimson SeaStor OSD Weekly Meeting","description":"","frontmatter":{"title":"2019-03-19:: Crimson SeaStor OSD Weekly Meeting","date":"2019-03-19T00:00:00.000Z","updated":"None","tags":["Ceph","Distributed Storage","Crimson SeaStor","OSD Weekly Meeting","Performance Testing"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-03-19_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","filePath":"posts/2019/2019-03-19_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","lastUpdated":1780460162000}'),i={name:"posts/2019/2019-03-19_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md"};function e(l,t,g,_,a,S){return n(),s("div",null,[...t[0]||(t[0]=[r("<p>本次会议主要讨论了Ceph分布式存储项目的最新进展，包括性能测试、代码优化和功能开发等方面。</p><p><strong>参会人员</strong>： Joan、Sam、Kim、Steve、Jim等</p><p><strong>关键细节</strong>：</p><ul><li><strong>Joan</strong>： 正在进行Ceph分布式追踪的研究，尝试将PG和PD的等待列表建模在辅助工具中，并研究快照和克隆相关功能。</li><li><strong>Kim</strong>： 专注于修复Crimson消息传递中的问题，并通过测试多个客户端来模拟性能测试。</li><li><strong>Sam</strong>： 审查FSM代码，并尝试简化PG对等状态机的实现。</li><li><strong>Steve</strong>： 开发v2协议实现，并尝试将加密和认证功能集成到Crimson消息传递中。</li><li><strong>Jim</strong>： 开发新的测试客户端，用于进行性能测试。</li></ul><p><strong>讨论的主要议题</strong>：</p><ul><li><strong>性能测试</strong>： 如何通过多个客户端驱动Crimson消息传递来模拟性能测试。</li><li><strong>代码优化</strong>： 如何简化PG对等状态机的实现，以及如何利用sISTAR的consume方法来创建对齐的缓冲区。</li><li><strong>功能开发</strong>： 如何将加密和认证功能集成到Crimson消息传递中。</li></ul><p><strong>决定的事项</strong>：</p><ul><li><strong>Joan</strong>： 继续研究快照和克隆相关功能。</li><li><strong>Kim</strong>： 继续修复Crimson消息传递中的问题，并尝试通过测试多个客户端来模拟性能测试。</li><li><strong>Sam</strong>： 继续审查FSM代码，并尝试简化PG对等状态机的实现。</li><li><strong>Steve</strong>： 继续开发v2协议实现，并尝试将加密和认证功能集成到Crimson消息传递中。</li><li><strong>Jim</strong>： 继续开发新的测试客户端，用于进行性能测试。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li><strong>Joan</strong>： 将发送等待列表建模的辅助工具的代码。</li><li><strong>Kim</strong>： 将发送修复Crimson消息传递问题的代码。</li><li><strong>Sam</strong>： 将发送简化PG对等状态机的代码。</li><li><strong>Steve</strong>： 将发送v2协议实现的代码。</li><li><strong>Jim</strong>： 将发送新的测试客户端的代码。</li></ul><p><strong>其他事项</strong>：</p><ul><li><strong>分布式追踪</strong>： 将PG和PD的等待列表建模在辅助工具中。</li><li><strong>FSM</strong>： 审查并简化PG对等状态机的实现。</li><li><strong>Crimson</strong>： 修复消息传递中的问题，并通过测试多个客户端来模拟性能测试。</li><li><strong>v2协议</strong>： 开发并集成加密和认证功能。</li><li><strong>sISTAR</strong>： 利用consume方法创建对齐的缓冲区。</li></ul>",12)])])}const u=o(i,[["render",e]]);export{p as __pageData,u as default};
